:root {
  --bg: #1a1c2c;
  --card: #2a2d45;
  --primary: #ffcd75;
  --text: #f4f4f4;
  --muted: #a0a4b8;
  --accent: #38b764;
  --border: #4a4e6a;
  --font: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 18px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background-image: radial-gradient(circle, #2a2d45 1px, transparent 1px);
  background-size: 16px 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--border);
  padding: 24px;
  width: 100%;
  max-width: 400px;
  box-shadow: 8px 8px 0 #0f101a;
}

h1 {
  font-size: 1.8rem;
  text-align: center;
  margin-bottom: 24px;
  color: var(--primary);
  text-shadow: 2px 2px 0 #0f101a;
  letter-spacing: 2px;
}

.field {
  margin-bottom: 20px;
}

label, legend {
  display: block;
  font-size: 1rem;
  margin-bottom: 8px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

input[type="number"] {
  width: 100%;
  padding: 12px;
  font-family: var(--font);
  font-size: 1.2rem;
  background: var(--bg);
  border: 3px solid var(--border);
  color: var(--text);
  outline: none;
}

input[type="number"]:focus-visible {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(255, 205, 117, 0.4);
}

.tip-buttons {
  display: flex;
  gap: 12px;
}

.tip-btn {
  flex: 1;
  padding: 12px 8px;
  font-family: var(--font);
  font-size: 1.1rem;
  font-weight: bold;
  background: var(--bg);
  color: var(--text);
  border: 3px solid var(--border);
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
  box-shadow: 3px 3px 0 #0f101a;
}

.tip-btn:hover {
  background: #3a3d5a;
}

.tip-btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.tip-btn:active,
.tip-btn[aria-pressed="true"] {
  background: var(--primary);
  color: var(--bg);
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0 #0f101a;
}

.results {
  margin-top: 24px;
  border-top: 3px dashed var(--border);
  padding-top: 20px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 12px;
}

.result-label {
  color: var(--muted);
  font-size: 0.95rem;
}

.result-value {
  font-size: 1.4rem;
  font-weight: bold;
  color: var(--accent);
  text-shadow: 1px 1px 0 #0f101a;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
    box-shadow: 4px 4px 0 #0f101a;
  }
  h1 {
    font-size: 1.5rem;
  }
  .tip-btn {
    font-size: 1rem;
    padding: 10px 4px;
  }
}

const billInput = document.getElementById('bill');
const peopleInput = document.getElementById('people');
const tipButtons = document.querySelectorAll('.tip-btn');
const tipPerPersonEl = document.getElementById('tipPerPerson');
const totalPerPersonEl = document.getElementById('totalPerPerson');

let selectedTip = 0;

function formatCurrency(value) {
  return '$' + value.toFixed(2);
}

function calculate() {
  const bill = parseFloat(billInput.value) || 0;
  let people = parseInt(peopleInput.value, 10);
  if (isNaN(people) || people < 1) people = 1;

  const tipAmount = bill * (selectedTip / 100);
  const tipPerPerson = tipAmount / people;
  const totalPerPerson = (bill + tipAmount) / people;

  tipPerPersonEl.textContent = formatCurrency(tipPerPerson);
  totalPerPersonEl.textContent = formatCurrency(totalPerPerson);
}

function selectTip(percent) {
  selectedTip = percent;
  tipButtons.forEach(btn => {
    const isActive = parseInt(btn.dataset.tip, 10) === percent;
    btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
  });
  calculate();
}

tipButtons.forEach(btn => {
  btn.addEventListener('click', () => {
    selectTip(parseInt(btn.dataset.tip, 10));
  });
});

billInput.addEventListener('input', calculate);
peopleInput.addEventListener('input', calculate);

// Initial state: no tip selected, zero values
calculate();
